import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.Drp2S_UI.js";const g=JSON.parse('{"title":"RTL Layout & Rendering Engine Design","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/rtl-layout-design.md","filePath":"en/guide/rtl-layout-design.md","lastUpdated":1792653875000}'),d={name:"en/guide/rtl-layout-design.md"};function n(i,e,s,c,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="rtl-layout-rendering-engine-design" tabindex="-1">RTL Layout &amp; Rendering Engine Design <a class="header-anchor" href="#rtl-layout-rendering-engine-design" aria-label="Permalink to &quot;RTL Layout &amp; Rendering Engine Design&quot;">​</a></h1><blockquote><p>Historical design/migration record: T20 removed the legacy engine, mode selectors and browser text fallback. Follow <a href="./font-and-esm-migration.html">Fonts and ESM migration</a> for current integration; old paths below are not current APIs.</p></blockquote><blockquote><p>Goal: support Arabic and other RTL/LTR mixed layout on the existing flat <code>IElement[]</code> model; <strong>HarfBuzz is required for this phase</strong>; keep the layout/paint engine relatively independent to reduce Draw invasiveness.<br> Baseline: <a href="./architecture.html">Architecture</a>. Deferred work: <a href="./rtl-deferred-todo.html">RTL deferred TODO</a>.</p></blockquote><h2 id="_1-goals-and-decisions" tabindex="-1">1. Goals and decisions <a class="header-anchor" href="#_1-goals-and-decisions" aria-label="Permalink to &quot;1. Goals and decisions&quot;">​</a></h2><ol><li>Canvas-only layout/paint; metrics from HarfBuzz advances; self-computed visual coordinates; <strong>do not</strong> rely on global <code>ctx.direction</code>.</li><li>Precise caret and hit-testing including ligature interiors (cluster mapping).</li><li>Full Bidi (UAX#9): paragraph <code>ltr</code> / <code>rtl</code> / <code>auto</code>; alignment <code>start</code> / <code>end</code> / physical left-right / center / justify.</li><li>Rich text via per-character element styles (no separate AttributeRange store).</li><li>Editing: visual arrow keys, logical delete, IME, dual DOM caret sync.</li><li>DOM shell: CursorAgent textarea + toolbar; engine stays UI-framework free.</li><li>History: keep snapshots this phase; incremental history is <a href="./rtl-deferred-todo.html#defer-009">DEFER-009</a>.</li></ol><p><strong>Out of scope for storage</strong>: migrating to standalone <code>Paragraph[]</code> + <code>AttributeRange</code>; scattering HB/Bidi into <code>Draw.ts</code> / particles.</p><h2 id="_2-current-gaps" tabindex="-1">2. Current gaps <a class="header-anchor" href="#_2-current-gaps" aria-label="Permalink to &quot;2. Current gaps&quot;">​</a></h2><p>Pipeline today is LTR-only (<code>ctx.direction = &#39;ltr&#39;</code>, <code>x += width</code>). Paragraphs are implicit <code>ZERO</code> boundaries. History is full snapshots.</p><table tabindex="0"><thead><tr><th>Spec concept</th><th>Current equivalent</th><th>Approach</th></tr></thead><tbody><tr><td><code>Paragraph.text</code></td><td>Join values between <code>ZERO</code>s</td><td>Logical scanner only</td></tr><tr><td><code>AttributeRange</code></td><td>Per-char style fields</td><td>Aggregate StyleRuns at layout</td></tr><tr><td><code>direction</code> / align</td><td>none / <code>rowFlex</code></td><td>Add <code>direction</code>; <code>start</code>/<code>end</code> on <code>rowFlex</code></td></tr><tr><td>Layout engine</td><td>inline <code>computeRowList</code></td><td>Independent <code>text-engine</code></td></tr><tr><td>HarfBuzz</td><td><code>measureText</code></td><td><strong>Required</strong> <code>HarfBuzzTextShaper</code></td></tr><tr><td>Reversible commands</td><td>snapshot closures</td><td><a href="./rtl-deferred-todo.html#defer-009">DEFER-009</a></td></tr></tbody></table><h2 id="_3-model-extensions" tabindex="-1">3. Model extensions <a class="header-anchor" href="#_3-model-extensions" aria-label="Permalink to &quot;3. Model extensions&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">direction</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TextDirection </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;ltr&#39; | &#39;rtl&#39; | &#39;auto&#39;</span></span></code></pre></div><p>Add <code>RowFlex.start</code> / <code>end</code>; keep physical <code>left</code>/<code>right</code>. Wire into zip/row attrs, content <code>defaultDirection</code> (<code>executeDirection</code>), UI mode <code>options.direction</code> (<code>executeUiDirection</code>, <code>ce-ui-rtl</code> — never canvas <code>dir=rtl</code>), <code>textEngine</code>, <code>fonts</code>, <code>caretMovement</code>. Runtime-only: <code>bidiLevel</code> / <code>visualIndex</code> / <code>clusterStart</code> / <code>clusterEnd</code>.</p><p><code>ParagraphScanner</code> yields logical spans; no persisted <code>paragraphId</code>.</p><p>Commands: <code>executeDirection</code>, <code>getRangeParagraphDirection</code>, HTML <code>dir</code> round-trip (full fidelity edge cases: <a href="./rtl-deferred-todo.html#defer-019">DEFER-019</a>).</p><h2 id="_4-independent-engine-boundary" tabindex="-1">4. Independent engine boundary <a class="header-anchor" href="#_4-independent-engine-boundary" aria-label="Permalink to &quot;4. Independent engine boundary&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/editor/core/text-engine/       # no Draw imports</span></span>
<span class="line"><span>src/editor/core/text-engine-host/  # only glue that may import IElement</span></span></code></pre></div><p><strong>Allowed</strong>: engine → own types + harfbuzz/opentype/bidi.<br><strong>Forbidden</strong>: engine → Draw/Command/Particle; calling HB inside <code>computeRowList</code>.</p><p>Host changes: Draw text path → <code>LayoutHostAdapter</code>; Position/Cursor → <code>HitTestAdapter</code>; TextParticle → <code>GlyphRenderer</code>; decorations → <code>mergeVisualRects</code>; dual path <code>textEngine: &#39;legacy&#39; | &#39;harfbuzz&#39;</code>; transitional <code>mapToLegacyRow</code> (<a href="./rtl-deferred-todo.html#defer-016">DEFER-016</a>).</p><h2 id="_5-layout-pipeline" tabindex="-1">5. Layout pipeline <a class="header-anchor" href="#_5-layout-pipeline" aria-label="Permalink to &quot;5. Layout pipeline&quot;">​</a></h2><p><code>TextSpan[]</code> → resolveDirection → Bidi → StyleRuns → <strong>HarfBuzz</strong> → LineBreaker → Alignment → <code>LayoutResult</code>.</p><p>HarfBuzz flow:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>StyleRun → FontManager → hb.shape → ShapedGlyph[] { glyphId, cluster, ax, dx, charStart, charEnd }</span></span></code></pre></div><p>Invariants: logical <code>elementList</code> order unchanged; visual order only in layout results; <code>IElementPosition.index</code> stays logical; clusters enabled this phase. LaTeX SVG does <strong>not</strong> go through HarfBuzz.</p><h2 id="_6-input-simulated-caret-delete" tabindex="-1">6. Input, simulated caret, delete <a class="header-anchor" href="#_6-input-simulated-caret-delete" aria-label="Permalink to &quot;6. Input, simulated caret, delete&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Behavior</th></tr></thead><tbody><tr><td>Left/Right</td><td>Visual neighbors by default</td></tr><tr><td>Backspace/Delete</td><td><strong>Logical</strong> delete</td></tr><tr><td>Home/End</td><td>Visual line ends</td></tr><tr><td>Click/drag</td><td><code>pointToLogicalIndex</code></td></tr><tr><td>IME</td><td>Agent <code>dir</code> = paragraph direction; skip keydown while composing</td></tr></tbody></table><p><strong>Simulated caret (required):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logicalIndex → HitTestAdapter.caretMetrics() → sync cursorDom + agentCursorDom</span></span></code></pre></div><p>Do not assume caret sticks to <code>rightTop</code>. Blink bar and Agent must share one metrics source. Ligature interpolation matches hit-testing. Page offset remains in Cursor.</p><p><strong>Delete listening (required):</strong></p><p>Keep <code>keydown</code> → <code>backspace</code> / <code>del</code>. Do not make textarea <code>beforeinput</code> the primary path (<a href="./rtl-deferred-todo.html#defer-021">DEFER-021</a>). Preserve control/hide/trace/table rules in existing handlers. One grapheme/cluster per Backspace in Arabic. After delete: <code>render</code> → <code>drawCursor</code>. Visual-adjacent delete mode: <a href="./rtl-deferred-todo.html#defer-022">DEFER-022</a>.</p><h2 id="_7-rendering" tabindex="-1">7. Rendering <a class="header-anchor" href="#_7-rendering" aria-label="Permalink to &quot;7. Rendering&quot;">​</a></h2><p>GlyphRenderer inside engine; TextParticle becomes a thin delegate under <code>harfbuzz</code>. Use <code>mergeVisualRects</code> for underline/strikeout/highlight/trace/group/control border/selection. Non-text particles stay outside the engine.</p><h2 id="_8-canvas-paths-beyond-the-big-five" tabindex="-1">8. Canvas paths beyond the “big five” <a class="header-anchor" href="#_8-canvas-paths-beyond-the-big-five" aria-label="Permalink to &quot;8. Canvas paths beyond the “big five”&quot;">​</a></h2><p><strong>A (this phase):</strong> <code>ctx.direction</code>, AbstractRichText family, Trace, Group, ControlBorder, Hyperlink/Sub/Superscript (engine rows via GlyphRenderer), basic float surround, DATE segment complete.<br><strong>B (with P3):</strong> List indent/marker side, LineBreak, Placeholder; LineNumber/PageNumber <strong>side mirroring</strong> → <a href="./rtl-deferred-todo.html#defer-015">DEFER-015</a>.<br><strong>C:</strong> page-level chrome / print. Plain-text chrome (watermark / page-number format / page-break label / image caption) uses <code>layoutPlainText</code> + <code>GlyphRenderer</code> via <code>drawPlainText</code> when HarfBuzz is ready; otherwise <code>fillText</code>. <strong>LTR/RTL mode</strong> <code>options.direction</code> (<code>ltr</code>|<code>rtl</code>, default <code>ltr</code>) mirrors editor UI chrome only (<code>ce-ui-rtl</code> class on the container — <strong>never</strong> <code>dir=rtl</code> on the canvas root, which breaks absolute caret hit-testing; toolbar/footer/context menus may set their own <code>dir</code>) and supplies the default <code>element.direction</code> for <strong>newly created</strong> lines/tables; it must <strong>not</strong> affect hit-testing or body paint, rewrite existing content direction, remirror undeclared tables, or reflow the text area on toggle. Separate from paragraph <code>executeDirection</code> / <code>defaultDirection</code>. Use <code>executeUiDirection</code>. Mode toggle visibility is controlled by <code>uiDirectionToggle</code> (default true). <strong>D:</strong> tables/controls → <a href="./rtl-deferred-todo.html">deferred TODO</a>. DATE/LABEL vs GlyphRenderer <a href="./rtl-deferred-todo.html#defer-023">DEFER-023</a> and in-paragraph Control embeds <a href="./rtl-deferred-todo.html#defer-024">DEFER-024</a> are complete; surround/column mixed-layout acceptance remains <a href="./rtl-deferred-todo.html#defer-025">DEFER-025</a>.</p><h2 id="_9-svg" tabindex="-1">9. SVG <a class="header-anchor" href="#_9-svg" aria-label="Permalink to &quot;9. SVG&quot;">​</a></h2><p>No DOM document SVG on trunk. Do <strong>not</strong> mirror LaTeX SVG paths for document RTL. Badge right anchor: <a href="./rtl-deferred-todo.html#defer-005">DEFER-005</a>. <code>feature/svg</code> branch: <a href="./rtl-deferred-todo.html#defer-013">DEFER-013</a>.</p><h2 id="_10-history" tabindex="-1">10. History <a class="header-anchor" href="#_10-history" aria-label="Permalink to &quot;10. History&quot;">​</a></h2><p>Snapshots remain; incremental command history is deferred (<a href="./rtl-deferred-todo.html#defer-009">DEFER-009</a>).</p><h2 id="_11-testing" tabindex="-1">11. Testing <a class="header-anchor" href="#_11-testing" aria-label="Permalink to &quot;11. Testing&quot;">​</a></h2><p>Lock fonts for LTR regression under HB. Unit: bidi, clusters, caret, rect merge, FontManager. Cypress: Arabic ligature click/arrows, mixed runs, IME dir, Backspace/Delete caret, toolbar direction. CI must load WASM + font fixtures.</p><h2 id="_12-roadmap" tabindex="-1">12. Roadmap <a class="header-anchor" href="#_12-roadmap" aria-label="Permalink to &quot;12. Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Goal</th></tr></thead><tbody><tr><td>P0</td><td>Docs (architecture, this design, deferred TODO)</td></tr><tr><td>P1</td><td>Model fields + commands</td></tr><tr><td>P2</td><td>Independent engine + HarfBuzz + adapters + switch</td></tr><tr><td>P3</td><td>RTL + dual DOM caret + logical delete + decorations/lists</td></tr><tr><td>P4</td><td>Mixed runs + start/end + surround</td></tr><tr><td>P5+</td><td>See deferred TODO</td></tr></tbody></table><h2 id="_13-links" tabindex="-1">13. Links <a class="header-anchor" href="#_13-links" aria-label="Permalink to &quot;13. Links&quot;">​</a></h2><ul><li><a href="./architecture.html">Architecture</a></li><li><a href="./rtl-deferred-todo.html">RTL deferred TODO</a></li><li><a href="./schema.html">Schema</a></li><li><a href="./option.html">Option</a></li></ul>`,44)])])}const u=t(d,[["render",n]]);export{g as __pageData,u as default};
